// Index maps for instantaneous lookup
const SYMBOL_MAP = new Map()
const NAME_MAP = new Map()
const NUMBER_MAP = new Map()

PERIODIC_TABLE.forEach((el) => {
  SYMBOL_MAP.set(el.symbol.toUpperCase(), el)
  NAME_MAP.set(el.name.toLowerCase(), el)
  NUMBER_MAP.set(el.number, el)
})

export function isElement(query) {
  if (!query || typeof query !== 'string') return false
  const clean = query.trim()
  return SYMBOL_MAP.has(clean.toUpperCase()) || NAME_MAP.has(clean.toLowerCase())
}

export function getElement(query) {
  if (!query) return null
  if (typeof query === 'number') return NUMBER_MAP.get(query) || null
  const clean = String(query).trim()
  return (
    SYMBOL_MAP.get(clean.toUpperCase()) ||
    NAME_MAP.get(clean.toLowerCase()) ||
    NUMBER_MAP.get(parseInt(clean, 10)) ||
    null
  )
}

export function getElementBySymbol(symbol) {
  if (!symbol) return null
  return SYMBOL_MAP.get(String(symbol).trim().toUpperCase()) || null
}

export function getElementColor(symbol) {
  const el = getElementBySymbol(symbol)
  return el?.color || '#94a3b8'
}

export function getElementVdwRadius(symbol) {
  const el = getElementBySymbol(symbol)
  return el?.vdwRadius || 1.7
}

/**
 * Calculates stoichiometric element breakdown for a formula or atom set
 */
export function calculateElementComposition(formula, atoms = []) {
  const counts = {}

  if (atoms && atoms.length > 0) {
    atoms.forEach((a) => {
      const sym = (a.element || 'C').toUpperCase()
      counts[sym] = (counts[sym] || 0) + 1
    })
  } else if (formula && typeof formula === 'string') {
    const regex = /([A-Z][a-z]?)(\d*)/g
    let match
    while ((match = regex.exec(formula)) !== null) {
      if (!match[1]) continue
      const sym = match[1].toUpperCase()
      const count = match[2] ? parseInt(match[2], 10) : 1
      counts[sym] = (counts[sym] || 0) + count
    }
  }

  const elementsList = []
  let totalMass = 0

  for (const [sym, count] of Object.entries(counts)) {
    const info = getElementBySymbol(sym) || {
      name: sym,
      number: 0,
      mass: 12.0,
      color: '#94a3b8',
      electronConfig: 'N/A',
      oxidationStates: [],
    }
    const massContrib = count * info.mass
    totalMass += massContrib
    elementsList.push({
      symbol: sym,
      name: info.name,
      atomicNumber: info.number,
      atomicMass: info.mass,
      count,
      color: info.color,
      electronConfig: info.electronConfig,
      oxidationStates: info.oxidationStates,
      massContribution: massContrib,
    })
  }

  const safeTotalMass = totalMass > 0 ? totalMass : 1
  return elementsList
    .map((e) => ({
      ...e,
      weightPercent: parseFloat(((e.massContribution / safeTotalMass) * 100).toFixed(2)),
    }))
    .sort((a, b) => b.weightPercent - a.weightPercent)
}
